{
  "title": "VPN Troubleshooting Checklist",
  "generated_date": "2026-08-03",
  "note": "This checklist synthesizes information from multiple KB articles. kb_006 (VPN Client Update Notice) takes priority over kb_001 (Company VPN Connection Guide) as of 2026-02-25.",
  "current_client": {
    "name": "GlobalProtect VPN Client",
    "provider": "Palo Alto Networks",
    "source": "kb_006",
    "note": "FortiClient is no longer supported starting March 1, 2026. Migrate to GlobalProtect."
  },
  "connection_steps": [
    {
      "step": 1,
      "action": "Download and install GlobalProtect VPN client",
      "url": "https://vpn.company.com/downloads",
      "source": "kb_006"
    },
    {
      "step": 2,
      "action": "Open GlobalProtect and select Remote Access",
      "source": "kb_006"
    },
    {
      "step": 3,
      "action": "Enter server address: vpn.company.com",
      "source": "kb_001, kb_006"
    },
    {
      "step": 4,
      "action": "Log in with company email account and password",
      "source": "kb_001, kb_006"
    },
    {
      "step": 5,
      "action": "Select connection mode (Full Tunnel Mode recommended)",
      "source": "kb_001"
    }
  ],
  "troubleshooting": {
    "connection_timeout": [
      {
        "issue": "Connection timeout",
        "solutions": [
          {
            "solution": "Check your network connection",
            "source": "kb_001"
          },
          {
            "solution": "Ensure firewall is not blocking VPN port 443",
            "source": "kb_001, kb_007"
          },
          {
            "solution": "Refer to firewall settings in VPN Connection Guide",
            "source": "kb_007"
          }
        ]
      }
    ],
    "authentication_failure": [
      {
        "issue": "Authentication failure / Password expired",
        "solutions": [
          {
            "solution": "Confirm password has not expired (passwords must be changed every 90 days)",
            "source": "kb_001"
          },
          {
            "solution": "Reset password at https://password.company.com",
            "source": "kb_001, kb_005"
          },
          {
            "solution": "Use WeCom IT bot for password reset",
            "source": "kb_005"
          },
          {
            "solution": "Contact IT hotline ext.8888",
            "source": "kb_001, kb_005, kb_006"
          }
        ]
      }
    ],
    "cannot_access_intranet": [
      {
        "issue": "Cannot access intranet after connecting",
        "solutions": [
          {
            "solution": "Try disconnecting and reconnecting",
            "source": "kb_001"
          },
          {
            "solution": "Contact IT hotline ext.8888",
            "source": "kb_001"
          }
        ]
      }
    ],
    "frequent_disconnections": [
      {
        "issue": "Frequent disconnections",
        "solutions": [
          {
            "solution": "Switch to 5GHz WiFi",
            "source": "kb_007"
          },
          {
            "solution": "Use a wired connection",
            "source": "kb_007"
          }
        ]
      }
    ],
    "file_sync_failures": [
      {
        "issue": "File sync failures",
        "solutions": [
          {
            "solution": "Check VPN connection status",
            "source": "kb_007"
          },
          {
            "solution": "Verify Confluence space permissions",
            "source": "kb_007"
          },
          {
            "solution": "For large files (>100MB), use company FTP server",
            "source": "kb_007"
          }
        ]
      }
    ]
  },
  "important_notes": [
    {
      "note": "VPN password syncs with email password and must be changed every 90 days",
      "source": "kb_001"
    },
    {
      "note": "Special VPN permissions must be requested in advance for overseas business trips",
      "source": "kb_001"
    },
    {
      "note": "MFA is mandatory for all systems. Recommended: Microsoft Authenticator. Backup: SMS verification code",
      "source": "kb_005"
    },
    {
      "note": "Password policy: Minimum 12 characters, must include uppercase, lowercase, numbers, and special characters",
      "source": "kb_005"
    }
  ],
  "contact_info": {
    "it_hotline": "ext.8888",
    "password_reset_url": "https://password.company.com",
    "vpn_download_url": "https://vpn.company.com/downloads",
    "source": "kb_001, kb_005, kb_006"
  },
  "contradictions_resolved": [
    {
      "conflict": "kb_001 recommends FortiClient; kb_006 states FortiClient is deprecated",
      "resolution": "kb_006 (2026-02-25) takes priority over kb_001 (2026-01-15). Users must migrate to GlobalProtect client.",
      "priority_source": "kb_006"
    }
  ]
}
